// Función mágica que convierte el nombre largo en corto si existe
const getNombreCorto = (nombreLargo) => {
    if (!nombreLargo) return "Desconocido";

    const busquedaLimpia = nombreLargo.trim().toUpperCase().mon



    const key = nombreLargo.trim().toUpperCase();
    return DICCIONARIO_NOMBRES_CORTOS[key] || nombreLargo; // Si no lo encuentra, deja el largo intacto
};
