// ===============================================
// FASE 1: RANKINGS DINÁMICOS Y FILTRADOS
// ===============================================
function calcularRankings(candidatos, partidoFiltro = "ALL") {
    // 'pool' es la lista filtrada por el dropdown (afectará a la columna 1)
    let pool = candidatos;
    if (partidoFiltro !== "ALL") pool = candidatos.filter(c => c.partidoActual === partidoFiltro);

    // RANKING 1: Cambios de Camiseta usando la nueva lógica de clusters
    let rankingCamisetas = pool.map(c => {
        return { ...c, metrica: calcularCamisetasUnicas(c) };
    }).sort((a, b) => b.metrica - a.metrica).slice(0, 5);

    // RANKING 2: PARTIDOS CON MÁS CAMALEONES (SIEMPRE GLOBAL)
    const conteoPartidos = {};
    
    // Usamos la nueva lógica de clusters para saber si el candidato es camaleón
    candidatos.forEach(c => {
        let totalCamisetas = calcularCamisetasUnicas(c);
        if (totalCamisetas > 1) {
            conteoPartidos[c.partidoActual] = (conteoPartidos[c.partidoActual] || 0) + 1;
        }
    });

    let rankingPartidos = Object.entries(conteoPartidos)
        .map(([nombrePartido, cantidad]) => {
            const idPart = normalizarId(nombrePartido);
            const logoPartido = diccionarioPartidos[idPart] ? diccionarioPartidos[idPart].logo : null;
            return {
                nombre: nombrePartido,
                metrica: cantidad,
                partidoActual: null, // Evita la medallita doble
                idFoto: logoPartido  // Manda el logo al círculo principal
            };
        })
        .sort((a, b) => b.metrica - a.metrica)
        .slice(0, 5);

    return [
        { titulo: "Top 5 con más camisetas", data: rankingCamisetas, label: "camisetas" },
        { titulo: "Partidos con más camaleones", data: rankingPartidos, label: "candidatos" }
    ];
}



function describirPostulacion(candidato) {
    const registros = candidato.candidaturasActuales || [];
    const capitalizar = texto => String(texto || '').toLocaleLowerCase('es').replace(/(^|[\s-])\p{L}/gu, c => c.toLocaleUpperCase('es')).replace(/\bDe\b/g, 'de').replace(/\bDel\b/g, 'del');
    const etiquetas = registros.map(r => {
        const cargo = String(r.cargo || '').toLocaleLowerCase('es');
        const cargoVisible = cargo.charAt(0).toLocaleUpperCase('es') + cargo.slice(1);
        const lugar = r.tipo_eleccion === 'MUNICIPAL PROVINCIAL' || /PROVINCIAL/.test(r.cargo || '')
            ? 'Lima Metropolitana' : capitalizar(r.distrito);
        return [cargoVisible, lugar].filter(Boolean).join(' · ');
    });
    return [...new Set(etiquetas)].join(' / ');
}
function etiquetaPostulacion(candidato) {
    const texto = describirPostulacion(candidato);
    return texto ? `<div class="candidate-postulation">${escapar(texto)}</div>` : '';
}
function logoDeCamiseta(partido) {
    const info = diccionarioPartidos[normalizarId(partido)];
    if (info?.logo) return info.logo;
    if (!info?.tronco) return null;
    const logos = [...new Set(Object.values(diccionarioPartidos).filter(p => p.tronco === info.tronco && p.logo).map(p => p.logo))];
    return logos.length === 1 ? logos[0] : null;
}
function renderRankings(rankingsData) {
    renderRankingTrayectorias(rankingsData[0].data, 'camisetas');
    const container = document.getElementById('ranking-partidos-container');
    if (!container) return;
    container.innerHTML = rankingsData[1].data.map(c => {
        const nombre = getNombreCorto(c.nombre);
        const total = todosLosCandidatos.filter(cand => cand.partidoActual === c.nombre).length;
        const porcentaje = total ? (100 * c.metrica / total).toLocaleString('es-ES', {minimumFractionDigits: 1, maximumFractionDigits: 1}) : '0';
        const color = CONFIG.colores.partidos[c.nombre] || '#95A5A6';
        const iniciales = nombre.substring(0, 2).toUpperCase();
        const avatar = c.idFoto ? `<img src="${getUrlImagen(c.idFoto)}" alt="${escapar(nombre)}" class="loser-avatar party-ranking-avatar" onerror="this.hidden=true; this.nextElementSibling.hidden=false"/><div class="loser-avatar party-ranking-avatar" hidden>${escapar(iniciales)}</div>` : `<div class="loser-avatar party-ranking-avatar">${escapar(iniciales)}</div>`;
        return `<div class="loser-card" style="border-top: 3px solid ${color};">${avatar}<div class="loser-name">${escapar(nombre)}</div><div class="candidate-postulation">${porcentaje}% de sus ${total} candidatos</div><div class="loser-stats postulations-stats">${c.metrica} candidatos</div></div>`;
    }).join('');
}

