let fichajesCorte = '2026-01-07';
let fichajesVentana = 'ultimoDia';
function setupFichajes() {
    document.querySelectorAll('[data-fichajes-corte]').forEach(button => button.addEventListener('click', () => {
        fichajesCorte = button.dataset.fichajesCorte;
        document.querySelectorAll('[data-fichajes-corte]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.fichajesCorte === fichajesCorte)));
        renderFichajes();
    }));
    document.querySelectorAll('[data-fichajes-ventana]').forEach(button => button.addEventListener('click', () => {
        fichajesVentana = button.dataset.fichajesVentana;
        document.querySelectorAll('[data-fichajes-ventana]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.fichajesVentana === fichajesVentana)));
        renderFichajes();
    }));
    renderFichajes();
}
function logoFichaje(partido) {
    const logo = diccionarioPartidos[normalizarId(partido)]?.logo;
    return logo ? `<img class="fichajes-logo" src="${getUrlImagen(logo)}" alt="${escapar(partido)}" onerror="this.style.display='none'">` : '';
}
function renderFichajes() {
    const todos = window.DATOS_V5.resumenAfiliaciones.filter(r => r.fechaReferencia === fichajesCorte);
    const ranking = todos.map(r => ({partido:r.partido, cantidad:r.ventanas[fichajesVentana].cantidad}))
        .filter(r => r.cantidad > 0).sort((a,b) => b.cantidad-a.cantidad || a.partido.localeCompare(b.partido, 'es')).slice(0,10);
    const max = ranking[0]?.cantidad || 1;
    const el=document.getElementById('fichajes-ranking');
    el.innerHTML = ranking.length ? '<div class="fichajes-heading"><span>Top 10 organizaciones</span><span>Candidatos</span></div>' + ranking.map((r,i) => `
        <div class="fichajes-row" data-partido="${escapar(r.partido)}" data-cantidad="${r.cantidad}">
            <span class="fichajes-position">${i+1}</span><div><div class="fichajes-party">${logoFichaje(r.partido)}<span>${escapar(getNombreCorto(r.partido))}</span></div>
            <div class="fichajes-track" aria-hidden="true"><div class="fichajes-fill" style="width:${r.cantidad/max*100}%"></div></div></div>
            <span class="fichajes-count">${r.cantidad}</span></div>`).join('') : '<div class="fichajes-empty">Sin afiliaciones registradas en esta ventana.</div>';
    const etiquetas={ultimoDia:'Último día',ultimos7Dias:'Última semana',ultimos30Dias:'Últimos 30 días',ultimos6Meses:'Últimos 6 meses'};
    const fecha=fichajesCorte.split('-').reverse().join('/');
    document.getElementById('fichajes-caption').textContent=`${etiquetas[fichajesVentana]} · Corte: ${fecha} · ${todos.reduce((sum,r)=>sum+r.ventanas[fichajesVentana].cantidad,0)} candidatos en total. Se utiliza la afiliación vigente con fecha válida.`;
}

function renderRankingPerdedores(candidatos) {
    renderRankingTrayectorias(candidatos, 'derrotas');
}

function renderRankingPostulaciones(candidatos) {
    renderRankingTrayectorias(candidatos, 'postulaciones');
}

function renderRankingTrayectorias(candidatos, tipo) {
    const esPostulaciones = tipo === 'postulaciones';
    const esCamisetas = tipo === 'camisetas';
    const container = document.getElementById(esCamisetas ? 'ranking-camisetas-container' : esPostulaciones ? 'ranking-postulaciones-container' : 'ranking-perdedores-container');
    if(!container) return;

    // --- BUSCADOR INTELIGENTE DE LOGOS ---
    const encontrarArchivoLogo = (nombreBuscado) => {
        if (!nombreBuscado || typeof diccionarioPartidos === 'undefined') return null;
        const nombreLimpio = nombreBuscado.trim().toUpperCase();
        for (const key in diccionarioPartidos) {
            const data = diccionarioPartidos[key];
            if (data && data.nombre && data.nombre.trim().toUpperCase() === nombreLimpio) {
                if (data.logo && data.logo.trim() !== "") return data.logo; 
            }
        }
        return null;
    };

    // 1. Encontrar a los que nunca ganaron
    let perdedores = candidatos.filter(c => {
        if (esPostulaciones || esCamisetas) return c.metricas.totalPostulaciones > 0;
        let historial = c.historialElectoral;
        if(!historial || !Array.isArray(historial) || historial.length === 0) return false; 
        
        let victorias = historial.filter(h => h.elegido && h.elegido.toUpperCase().trim() === 'SI').length;
        return victorias === 0 && c.metricas.derrotasHistoricas > 0;
    });

    // 2. Contar todas sus postulaciones
    let perdedoresMapeados = perdedores.map(c => {
        let totalPostulaciones = esCamisetas ? c.metricas.camisetasDistintas : esPostulaciones ? c.metricas.totalPostulaciones : c.metricas.derrotasHistoricas;
        return { ...c, totalPostulaciones };
    });

    // 3. Ordenar de mayor a menor derrotas y sacar el Top 5
    perdedoresMapeados.sort((a, b) => b.totalPostulaciones - a.totalPostulaciones || ((esPostulaciones || esCamisetas) ? a.nombre.localeCompare(b.nombre, 'es') : 0));
    let topPerdedores = perdedoresMapeados.slice(0, 5);

    // 4. Se conserva el orden descendente de izquierda a derecha.

    // 5. Generar el HTML
    let html = '';
    topPerdedores.forEach(c => {
        let pActual = c.partidoActual || "INDEPENDIENTE";
        let colorPartido = (typeof CONFIG !== 'undefined' && CONFIG.colores.partidos[pActual]) ? CONFIG.colores.partidos[pActual] : "#95A5A6";
        
        // Foto del candidato
        let iniciales = c.nombre ? c.nombre.substring(0, 2).toUpperCase() : "XX";
        let fotoHtml = c.idFoto ? 
            `<img src="${typeof getUrlImagen === 'function' ? getUrlImagen(c.idFoto) : `https://fabmonge.github.io/Camisetas_Lima_2026/imagenes_voto_informado/${c.idFoto}`}" class="loser-avatar" onerror="this.outerHTML='<div class=\\'loser-avatar\\' style=\\'color:${colorPartido};\\'>${iniciales}</div>'"/>` : 
            `<div class="loser-avatar" style="color:${colorPartido};">${iniciales}</div>`;

        // Logo del partido (Búsqueda inteligente)
        let archivoLogo = encontrarArchivoLogo(pActual);
        let logoHtml = '';
        
        if (archivoLogo) {
            let logoUrl = typeof getUrlImagen === 'function' ? getUrlImagen(archivoLogo) : `https://fabmonge.github.io/Camisetas_Lima_2026/imagenes_voto_informado/${archivoLogo}`;
            // Si hay logo, lo ponemos como imagen dentro del círculo
            logoHtml = `<img src="${logoUrl}" alt="${pActual}" style="width: 100%; height: 100%; object-fit: contain; border-radius: 50%; background-color: #fff;" onerror="this.style.display='none'"/>`;
        } else {
            // Si no hay logo (o es independiente), pintamos el fondo del color del partido
            logoHtml = `<div style="width: 100%; height: 100%; border-radius: 50%; background-color: ${colorPartido};"></div>`;
        }

        html += `
            <div class="loser-card" style="border-top: 3px solid ${colorPartido};">
                <div class="loser-party-circle" title="Postula por: ${pActual}" style="border-color: ${colorPartido}; background-color: #fff;">
                    ${logoHtml}
                </div>
                ${fotoHtml}
                <div class="loser-name">${c.nombre}</div>${etiquetaPostulacion(c)}
                <div class="loser-stats${esPostulaciones || esCamisetas ? ' postulations-stats' : ''}">${c.totalPostulaciones} ${esCamisetas ? 'camisetas' : esPostulaciones ? 'postulaciones' : 'derrotas'}</div>
            </div>
        `;
    });

    container.innerHTML = html;
}